CREATE TYPE "Category" AS ENUM ('WORKPLACE', 'CONTENT', 'DEVELOPMENT', 'LEARNING', 'ECOMMERCE', 'DATA_ANALYSIS', 'LIFE');
CREATE TYPE "VoteValue" AS ENUM ('VALID', 'PARTIAL', 'INVALID');
CREATE TYPE "RunStatus" AS ENUM ('SUCCESS', 'ERROR', 'TIMEOUT');
CREATE TYPE "ModelProvider" AS ENUM ('OPENAI', 'ANTHROPIC', 'GOOGLE');

CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT, "email" TEXT, "image" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Technique" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "category" "Category" NOT NULL, "authorId" TEXT NOT NULL, "published" BOOLEAN NOT NULL DEFAULT false, "currentVersionId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Technique_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TechniqueVersion" ("id" TEXT NOT NULL, "techniqueId" TEXT NOT NULL, "versionNumber" INTEGER NOT NULL, "promptContent" TEXT NOT NULL, "modelId" TEXT NOT NULL, "temperature" DOUBLE PRECISION NOT NULL DEFAULT 0.7, "maxTokens" INTEGER NOT NULL DEFAULT 1024, "inputExample" TEXT, "outputExample" TEXT, "changelog" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TechniqueVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TechniqueRun" ("id" TEXT NOT NULL, "techniqueId" TEXT NOT NULL, "versionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "input" TEXT NOT NULL, "output" TEXT, "model" TEXT NOT NULL, "status" "RunStatus" NOT NULL, "durationMs" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TechniqueRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Vote" ("id" TEXT NOT NULL, "runId" TEXT NOT NULL, "userId" TEXT NOT NULL, "value" "VoteValue" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Vote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Collection" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "techniqueId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Collection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Tag" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Tag_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Model" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "provider" "ModelProvider" NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Model_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Account" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerAccountId" TEXT NOT NULL, "refresh_token" TEXT, "access_token" TEXT, "expires_at" INTEGER, "token_type" TEXT, "scope" TEXT, "id_token" TEXT, "session_state" TEXT, CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "sessionToken" TEXT NOT NULL, "userId" TEXT NOT NULL, "expires" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VerificationToken" ("identifier" TEXT NOT NULL, "token" TEXT NOT NULL, "expires" TIMESTAMP(3) NOT NULL);
CREATE TABLE "_TagToTechnique" ("A" TEXT NOT NULL, "B" TEXT NOT NULL);

