CREATE INDEX "Collection_techniqueId_idx" ON "Collection"("techniqueId");
CREATE UNIQUE INDEX "Tag_name_key" ON "Tag"("name");
CREATE INDEX "Tag_name_idx" ON "Tag"("name");
CREATE UNIQUE INDEX "Model_name_key" ON "Model"("name");
