ALTER TABLE "Technique" ADD CONSTRAINT "Technique_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Technique" ADD CONSTRAINT "Technique_currentVersionId_fkey" FOREIGN KEY ("currentVersionId") REFERENCES "TechniqueVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "TechniqueVersion" ADD CONSTRAINT "TechniqueVersion_techniqueId_fkey" FOREIGN KEY ("techniqueId") REFERENCES "Technique"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TechniqueVersion" ADD CONSTRAINT "TechniqueVersion_modelId_fkey" FOREIGN KEY ("modelId") REFERENCES "Model"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TechniqueRun" ADD CONSTRAINT "TechniqueRun_techniqueId_fkey" FOREIGN KEY ("techniqueId") REFERENCES "Technique"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TechniqueRun" ADD CONSTRAINT "TechniqueRun_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "TechniqueVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "TechniqueRun" ADD CONSTRAINT "TechniqueRun_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Vote" ADD CONSTRAINT "Vote_runId_fkey" FOREIGN KEY ("runId") REFERENCES "TechniqueRun"("id") ON DELETE CASCADE ON UPDATE CASCADE;
